###############################################


def split_identifier(identifier):
    """
    Split an SQL identifier into a two element tuple of (namespace, name).

    The identifier could be a table, column, or sequence name might be prefixed
    by a namespace.
    """
    try:
        namespace, name = identifier.split('"."')
    except ValueError:
        namespace, name = "", identifier
    return namespace.strip('"'), name.strip('"')


def truncate_name(identifier, length=None, hash_len=4):
    """
    Shorten an SQL identifier to a repeatable mangled version with the given
    length.

    If a quote stripped name contains a namespace, e.g. USERNAME"."TABLE,
    truncate the table portion only.
    """
    namespace, name = split_identifier(identifier)

    if length is None or len(name) <= length:
        return identifier

    digest = names_digest(name, length=hash_len)
    return "%s%s%s" % (
        '%s"."' % namespace if namespace else "",
        name[: length - hash_len],
        digest,
    )


def names_digest(*args, length):
    """
    Generate a 32-bit digest of a set of arguments that can be used to shorten
    identifying names.
    """
    h = md5(usedforsecurity=False)
    for arg in args:
        h.update(arg.encode())
    return h.hexdigest()[:length]


def format_number(value, max_digits, decimal_places):
    """
    Format a number into a string with the requisite number of digits and
    decimal places.
    """
    if value is None:
        return None
    context = decimal.getcontext().copy()
    if max_digits is not None:
        context.prec = max_digits
    if decimal_places is not None:
        value = value.quantize(
            decimal.Decimal(1).scaleb(-decimal_places), context=context
        )
    else:
        context.traps[decimal.Rounded] = 1
        value = context.create_decimal(value)
    return "{:f}".format(value)


def strip_quotes(table_name):
    """
    Strip quotes off of quoted table names to make them safe for use in index
    names, sequence names, etc. For example '"USER"."TABLE"' (an Oracle naming
    scheme) becomes 'USER"."TABLE'.
    """
    has_quotes = table_name.startswith('"') and table_name.endswith('"')
    return table_name[1:-1] if has_quotes else table_name

def get_connection_params(self):
    settings_dict = self.settings_dict
    # None may be used to connect to the default 'postgres' db
    if settings_dict["NAME"] == "" and not settings_dict["OPTIONS"].get("service"):
        raise ImproperlyConfigured(
            "settings.DATABASES is improperly configured. "
            "Please supply the NAME or OPTIONS['service'] value."
        )
    if len(settings_dict["NAME"] or "") > self.ops.max_name_length():
        raise ImproperlyConfigured(
            "The database name '%s' (%d characters) is longer than "
            "PostgreSQL's limit of %d characters. Supply a shorter NAME "
            "in settings.DATABASES."
            % (
                settings_dict["NAME"],
                len(settings_dict["NAME"]),
                self.ops.max_name_length(),
            )
        )
    if settings_dict["NAME"]:
        conn_params = {
            "dbname": settings_dict["NAME"],
            **settings_dict["OPTIONS"],
        }
    elif settings_dict["NAME"] is None:
        # Connect to the default 'postgres' db.
        settings_dict["OPTIONS"].pop("service", None)
        conn_params = {"dbname": "postgres", **settings_dict["OPTIONS"]}
    else:
        conn_params = {**settings_dict["OPTIONS"]}
    conn_params["client_encoding"] = "UTF8"

    conn_params.pop("assume_role", None)
    conn_params.pop("isolation_level", None)

    pool_options = conn_params.pop("pool", None)
    if pool_options and not is_psycopg3:
        raise ImproperlyConfigured("Database pooling requires psycopg >= 3")

    server_side_binding = conn_params.pop("server_side_binding", None)
    conn_params.setdefault(
        "cursor_factory",
        (
            ServerBindingCursor
            if is_psycopg3 and server_side_binding is True
            else Cursor
        ),
    )
    if settings_dict["USER"]:
        conn_params["user"] = settings_dict["USER"]
    if settings_dict["PASSWORD"]:
        conn_params["password"] = settings_dict["PASSWORD"]
    if settings_dict["HOST"]:
        conn_params["host"] = settings_dict["HOST"]
    if settings_dict["PORT"]:
        conn_params["port"] = settings_dict["PORT"]
    if is_psycopg3:
        conn_params["context"] = get_adapters_template(
            settings.USE_TZ, self.timezone
        )
        # Disable prepared statements by default to keep connection poolers
        # working. Can be reenabled via OPTIONS in the settings dict.
        conn_params["prepare_threshold"] = conn_params.pop(
            "prepare_threshold", None
        )
    return conn_params

@async_unsafe
def get_new_connection(self, conn_params):
    # self.isolation_level must be set:
    # - after connecting to the database in order to obtain the database's
    #   default when no value is explicitly specified in options.
    # - before calling _set_autocommit() because if autocommit is on, that
    #   will set connection.isolation_level to ISOLATION_LEVEL_AUTOCOMMIT.
    options = self.settings_dict["OPTIONS"]
    set_isolation_level = False
    try:
        isolation_level_value = options["isolation_level"]
    except KeyError:
        self.isolation_level = IsolationLevel.READ_COMMITTED
    else:
        # Set the isolation level to the value from OPTIONS.
        try:
            self.isolation_level = IsolationLevel(isolation_level_value)
            set_isolation_level = True
        except ValueError:
            raise ImproperlyConfigured(
                f"Invalid transaction isolation level {isolation_level_value} "
                f"specified. Use one of the psycopg.IsolationLevel values."
            )
    if self.pool:
        # If nothing else has opened the pool, open it now.
        self.pool.open()
        connection = self.pool.getconn()
    else:
        connection = self.Database.connect(**conn_params)
    if set_isolation_level:
        connection.isolation_level = self.isolation_level
    if not is_psycopg3:
        # Register dummy loads() to avoid a round trip from psycopg2's

class ConnectionHandler(BaseConnectionHandler):
    settings_name = "DATABASES"
    # Connections needs to still be an actual thread local, as it's truly
    # thread-critical. Database backends should use @async_unsafe to protect
    # their code from async contexts, but this will give those contexts
    # separate connections in case it's needed as well. There's no cleanup
    # after async contexts, though, so we don't allow that if we can help it.
    thread_critical = True

    def configure_settings(self, databases):
        databases = super().configure_settings(databases)
        if databases == {}:
            databases[DEFAULT_DB_ALIAS] = {"ENGINE": "django.db.backends.dummy"}
        elif DEFAULT_DB_ALIAS not in databases:
            raise ImproperlyConfigured(
                f"You must define a '{DEFAULT_DB_ALIAS}' database."
            )
        elif databases[DEFAULT_DB_ALIAS] == {}:
            databases[DEFAULT_DB_ALIAS]["ENGINE"] = "django.db.backends.dummy"

        # Configure default settings.
        for conn in databases.values():
            conn.setdefault("ATOMIC_REQUESTS", False)
            conn.setdefault("AUTOCOMMIT", True)
            conn.setdefault("ENGINE", "django.db.backends.dummy")
            if conn["ENGINE"] == "django.db.backends." or not conn["ENGINE"]:
                conn["ENGINE"] = "django.db.backends.dummy"
            conn.setdefault("CONN_MAX_AGE", 0)
            conn.setdefault("CONN_HEALTH_CHECKS", False)
            conn.setdefault("OPTIONS", {})
            conn.setdefault("TIME_ZONE", None)
            for setting in ["NAME", "USER", "PASSWORD", "HOST", "PORT"]:
                conn.setdefault(setting, "")

            test_settings = conn.setdefault("TEST", {})
            default_test_settings = [
                ("CHARSET", None),
                ("COLLATION", None),
                ("MIGRATE", True),
                ("MIRROR", None),
                ("NAME", None),
            ]
            for key, value in default_test_settings:
                test_settings.setdefault(key, value)
        return databases

    @property
    def databases(self):
        # Maintained for backward compatibility as some 3rd party packages have
        # made use of this private API in the past. It is no longer used within
        # Django itself.
        return self.settings

    def create_connection(self, alias):
        db = self.settings[alias]
        backend = load_backend(db["ENGINE"])
        return backend.DatabaseWrapper(db, alias)


class ConnectionRouter:
    def __init__(self, routers=None):
        """
        If routers is not specified, default to settings.DATABASE_ROUTERS.
        """
        self._routers = routers

    @cached_property
    def routers(self):
        if self._routers is None:
            self._routers = settings.DATABASE_ROUTERS
        routers = []
        for r in self._routers:
            if isinstance(r, str):
                router = import_string(r)()
            else:
                router = r
            routers.append(router)
        return routers

    def _router_func(action):
        def _route_db(self, model, **hints):
            chosen_db = None
            for router in self.routers:
                try:
                    method = getattr(router, action)
                except AttributeError:
                    # If the router doesn't have a method, skip to the next
                    # one.
                    pass
                else:
                    chosen_db = method(model, **hints)
                    if chosen_db:
                        return chosen_db
            instance = hints.get("instance")
            if instance is not None and instance._state.db:
                return instance._state.db
            return DEFAULT_DB_ALIAS

        return _route_db

    db_for_read = _router_func("db_for_read")
    db_for_write = _router_func("db_for_write")

    def allow_relation(self, obj1, obj2, **hints):
        for router in self.routers:
            try:
                method = router.allow_relation
            except AttributeError:
                # If the router doesn't have a method, skip to the next one.
                pass
            else:
                allow = method(obj1, obj2, **hints)
                if allow is not None:
                    return allow
        return obj1._state.db == obj2._state.db

    def allow_migrate(self, db, app_label, **hints):
        for router in self.routers:
            try:
                method = router.allow_migrate
            except AttributeError:
                # If the router doesn't have a method, skip to the next one.
                continue

            allow = method(db, app_label, **hints)

            if allow is not None:
                return allow
        return True

    def allow_migrate_model(self, db, model):
        return self.allow_migrate(
            db,
            model._meta.app_label,
            model_name=model._meta.model_name,
            model=model,
        )

    def get_migratable_models(self, app_config, db, include_auto_created=False):
        """Return app models allowed to be migrated on provided db."""
        models = app_config.get_models(include_auto_created=include_auto_created)
        return [model for model in models if self.allow_migrate_model(db, model)]

def get_connection_params(self):
    kwargs = {
        "conv": django_conversions,
        "charset": "utf8mb4",
    }
    settings_dict = self.settings_dict
    if settings_dict["USER"]:
        kwargs["user"] = settings_dict["USER"]
    if settings_dict["NAME"]:
        kwargs["database"] = settings_dict["NAME"]
    if settings_dict["PASSWORD"]:
        kwargs["password"] = settings_dict["PASSWORD"]
    if settings_dict["HOST"].startswith("/"):
        kwargs["unix_socket"] = settings_dict["HOST"]
    elif settings_dict["HOST"]:
        kwargs["host"] = settings_dict["HOST"]
    if settings_dict["PORT"]:
        kwargs["port"] = int(settings_dict["PORT"])
    # We need the number of potentially affected rows after an
    # "UPDATE", not the number of changed rows.
    kwargs["client_flag"] = CLIENT.FOUND_ROWS
    # Validate the transaction isolation level, if specified.
    options = settings_dict["OPTIONS"].copy()
    isolation_level = options.pop("isolation_level", "read committed")
    if isolation_level:
        isolation_level = isolation_level.lower()
        if isolation_level not in self.isolation_levels:
            raise ImproperlyConfigured(
                "Invalid transaction isolation level '%s' specified.\n"
                "Use one of %s, or None."
                % (
                    isolation_level,
                    ", ".join("'%s'" % s for s in sorted(self.isolation_levels)),
                )
            )
    self.isolation_level = isolation_level
    kwargs.update(options)
    return kwargs

@async_unsafe
def get_new_connection(self, conn_params):
    connection = Database.connect(**conn_params)
    return connection

def init_connection_state(self):
    super().init_connection_state()
    assignments = []
    if self.features.is_sql_auto_is_null_enabled:
        # SQL_AUTO_IS_NULL controls whether an AUTO_INCREMENT column on
        # a recently inserted row will return when the field is tested
        # for NULL. Disabling this brings this aspect of MySQL in line
        # with SQL standards.
        assignments.append("SET SQL_AUTO_IS_NULL = 0")

    if self.isolation_level:
        assignments.append(
            "SET SESSION TRANSACTION ISOLATION LEVEL %s"
            % self.isolation_level.upper()
        )

    if assignments:
        with self.cursor() as cursor:
            cursor.execute("; ".join(assignments))

@async_unsafe
def create_cursor(self, name=None):
    cursor = self.connection.cursor()
    return CursorWrapper(cursor)

def _rollback(self):
    try:
        BaseDatabaseWrapper._rollback(self)
    except Database.NotSupportedError:
        pass

def _set_autocommit(self, autocommit):
    with self.wrap_database_errors:
        self.connection.autocommit(autocommit)

def disable_constraint_checking(self):

def get_connection_params(self):
    settings_dict = self.settings_dict
    if not settings_dict["NAME"]:
        raise ImproperlyConfigured(
            "settings.DATABASES is improperly configured. "
            "Please supply the NAME value."
        )
    kwargs = {
        "database": settings_dict["NAME"],
        "detect_types": Database.PARSE_DECLTYPES | Database.PARSE_COLNAMES,
        **settings_dict["OPTIONS"],
    }
    # Always allow the underlying SQLite connection to be shareable
    # between multiple threads. The safe-guarding will be handled at a
    # higher level by the `BaseDatabaseWrapper.allow_thread_sharing`
    # property. This is necessary as the shareability is disabled by
    # default in sqlite3 and it cannot be changed once a connection is
    # opened.
    if "check_same_thread" in kwargs and kwargs["check_same_thread"]:
        warnings.warn(
            "The `check_same_thread` option was provided and set to "
            "True. It will be overridden with False. Use the "
            "`DatabaseWrapper.allow_thread_sharing` property instead "
            "for controlling thread shareability.",
            RuntimeWarning,
        )
    kwargs.update({"check_same_thread": False, "uri": True})
    transaction_mode = kwargs.pop("transaction_mode", None)
    if (
        transaction_mode is not None
        and transaction_mode.upper() not in self.transaction_modes
    ):
        allowed_transaction_modes = ", ".join(
            [f"{mode!r}" for mode in sorted(self.transaction_modes)]
        )
        raise ImproperlyConfigured(
            f"settings.DATABASES[{self.alias!r}]['OPTIONS']['transaction_mode'] "
            f"is improperly configured to '{transaction_mode}'. Use one of "
            f"{allowed_transaction_modes}, or None."
        )
    self.transaction_mode = transaction_mode.upper() if transaction_mode else None

    init_command = kwargs.pop("init_command", "")
    self.init_commands = init_command.split(";")
    return kwargs

def get_database_version(self):
    return self.Database.sqlite_version_info

@async_unsafe
def get_new_connection(self, conn_params):
    conn = Database.connect(**conn_params)
    register_functions(conn)

    conn.execute("PRAGMA foreign_keys = ON")
    # The macOS bundled SQLite defaults legacy_alter_table ON, which
    # prevents atomic table renames.
    conn.execute("PRAGMA legacy_alter_table = OFF")
    for init_command in self.init_commands:
        if init_command := init_command.strip():
            conn.execute(init_command)
    return conn

def create_cursor(self, name=None):
    return self.connection.cursor(factory=SQLiteCursorWrapper)

@async_unsafe
def close(self):
    self.validate_thread_sharing()
    # If database is in memory, closing the connection destroys the
    # database. To prevent accidental data loss, ignore close requests on
    # an in-memory db.
    if not self.is_in_memory_db():
        BaseDatabaseWrapper.close(self)

def _savepoint_allowed(self):
    # When 'isolation_level' is not None, sqlite3 commits before each
    # savepoint; it's a bug. When it is None, savepoints don't make sense
    # because autocommit is enabled. The only exception is inside 'atomic'
    # blocks. To work around that bug, on SQLite, 'atomic' starts a

def get_connection_params(self):
    conn_params = self.settings_dict["OPTIONS"].copy()
    if "use_returning_into" in conn_params:
        del conn_params["use_returning_into"]
    return conn_params

@async_unsafe
def get_new_connection(self, conn_params):
    if self.pool:
        return self.pool.acquire()
    return Database.connect(
        user=self.settings_dict["USER"],
        password=self.settings_dict["PASSWORD"],
        dsn=dsn(self.settings_dict),
        **conn_params,
    )

def init_connection_state(self):
    super().init_connection_state()
    cursor = self.create_cursor()
    # Set the territory first. The territory overrides NLS_DATE_FORMAT
    # and NLS_TIMESTAMP_FORMAT to the territory default. When all of
    # these are set in single statement it isn't clear what is supposed
    # to happen.
    cursor.execute("ALTER SESSION SET NLS_TERRITORY = 'AMERICA'")
    # Set Oracle date to ANSI date format. This only needs to execute
    # once when we create a new connection. We also set the Territory
    # to 'AMERICA' which forces Sunday to evaluate to a '1' in
    # TO_CHAR().
    cursor.execute(
        "ALTER SESSION SET NLS_DATE_FORMAT = 'YYYY-MM-DD HH24:MI:SS'"
        " NLS_TIMESTAMP_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF'"
        + (" TIME_ZONE = 'UTC'" if settings.USE_TZ else "")
    )
    cursor.close()
    if "operators" not in self.__dict__:
        # Ticket #14149: Check whether our LIKE implementation will
        # work for this connection or we need to fall back on LIKEC.
        # This check is performed only once per DatabaseWrapper
        # instance per thread, since subsequent connections will use
        # the same settings.
        cursor = self.create_cursor()
        try:
            cursor.execute(
                "SELECT 1 FROM DUAL WHERE DUMMY %s"
                % self._standard_operators["contains"],
                ["X"],
            )
        except Database.DatabaseError:
            self.operators = self._likec_operators
            self.pattern_ops = self._likec_pattern_ops
        else:
            self.operators = self._standard_operators
            self.pattern_ops = self._standard_pattern_ops
        cursor.close()
    self.connection.stmtcachesize = 20
    # Ensure all changes are preserved even when AUTOCOMMIT is False.
    if not self.get_autocommit():
        self.commit()

@async_unsafe
def create_cursor(self, name=None):
    return FormatStylePlaceholderCursor(self.connection, self)

def _commit(self):
    if self.connection is not None:
        with debug_transaction(self, "COMMIT"), wrap_oracle_errors():
            return self.connection.commit()

# Oracle doesn't support releasing savepoints. But we fake them when query
# logging is enabled to keep query counts consistent with other backends.
def _savepoint_commit(self, sid):
    if self.queries_logged:
        self.queries_log.append(
            {
                "sql": "-- RELEASE SAVEPOINT %s (faked)" % self.ops.quote_name(sid),
                "time": "0.000",
            }
        )

def _set_autocommit(self, autocommit):
    with self.wrap_database_errors:
        self.connection.autocommit = autocommit

def check_constraints(self, table_names=None):
    """
    Check constraints by setting them to immediate. Return them to deferred
    afterward.
    """
    with self.cursor() as cursor:
        cursor.execute("SET CONSTRAINTS ALL IMMEDIATE")
        cursor.execute("SET CONSTRAINTS ALL DEFERRED")

def is_usable(self):
    try:
        self.connection.ping()
    except Database.Error:
        return False
    else:
        return True
